<!DOCTYPE html>
<html lang="zh">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Recipe Layout</title>
<style>
  body {
    font-family: "Microsoft YaHei", "PingFang SC", sans-serif;
    background-color: #ffffff;
    margin: 0;
    padding: 20px;
    display: flex;
    justify-content: center;
  }
  .container {
    position: relative;
    width: 660px;
    display: flex;
    justify-content: space-between;
  }
  .col {
    width: 300px;
    display: flex;
    flex-direction: column;
  }
  table {
    width: 100%;
    border-collapse: collapse;
    text-align: center;
    font-size: 14px;
    background-color: #ffffff;
    table-layout: fixed;
  }
  th, td {
    border: 1px solid #000000;
    padding: 6px 4px;
    height: 24px;
  }
  .title-row th {
    font-size: 15px;
    font-weight: bold;
    padding: 8px 4px;
  }
  .header-row th {
    font-size: 13px;
    font-weight: bold;
    line-height: 1.3;
  }
  .green-triangle {
    position: relative;
  }
  .green-triangle::before {
    content: '';
    position: absolute;
    top: 0;
    right: 0;
    width: 0;
    height: 0;
    border-top: 8px solid #228B22;
    border-left: 8px solid transparent;
  }

  /* Spacing to match the original spatial layout */
  .t2 { margin-top: 16px; }
  .t3 { margin-top: 60px; }
  .t4 { margin-top: 194px; }
  .t5 { margin-top: 40px; }

  .arrows {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 10;
  }
</style>
</head>
